1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { ArrowLeft, ArrowRight, Check, ImagePlus, Info, RotateCcw, Sparkles, X } from "lucide-react";
5	
6	import { AIProgress, stepsAt } from "@/components/ui/AIProgress";
7	import { Badge } from "@/components/ui/Badge";
8	import { Button } from "@/components/ui/Button";
9	import { Input, Textarea } from "@/components/ui/Field";
10	import { Modal } from "@/components/ui/Modal";
11	import { Segmented } from "@/components/ui/Segmented";
12	import { Logo } from "@/components/marketing/Logo";
13	import { featuresByCategory, NOT_OFFERED, selectedFeatures } from "@/lib/features";
14	import { getTemplate } from "@/lib/templates";
15	import {
16	  getLook,
17	  LOOK_DIRECTIONS,
18	  templatesForCategory,
19	  WIZARD_CATEGORIES,
20	  type LookDirection,
21	  type WizardCategory,
22	} from "@/lib/wizard";
23	
24	import {
25	  assembleInlineBrief,
26	  CREATE_CREDIT_ESTIMATE,
27	  EMPTY_INLINE_ANSWERS,
28	  hasInlineAnswers,
29	  LIMITS,
30	  TONES,
31	  type DensityFeel,
32	  type InlineAnswers,
33	  type TypeFeel,
34	} from "./inline-brief";
35	import { LOGO_ACCEPT, prepareLogo } from "./inline-logo";
36	
37	/**
38	 * The inline build wizard — five stages, opened in place on the Create Website
39	 * page rather than by navigating off to /wizard.
40	 *
41	 * ## What it is, and what it is not
42	 *
43	 * It is a way to WRITE A PROMPT, and it hands that prompt back through
44	 * `onComplete`. It never starts a build, never calls a model and never touches
45	 * the network: every stage is local string work over lib/wizard.ts and
46	 * lib/features.ts, so it behaves identically on a bad connection and costs
47	 * nothing to open. The public /wizard is untouched and still works exactly as
48	 * it did — this SHARES its assembly (`assemblePrompt`) rather than forking it,
49	 * so a change to the starter briefs reaches both.
50	 *
51	 * ## Every stage is skippable, and going back never costs an answer
52	 *
53	 * Stage 1 carries a "Skip to the prompt" that jumps straight to review with
54	 * whatever has been answered so far, and every stage before review has a "Skip
55	 * this step". Answers live in one state object for the whole session, so Back
56	 * and Next are lossless in both directions — including across a close and
57	 * reopen, which resumes exactly where the customer left off rather than
58	 * discarding their work for tidiness.
59	 *
60	 * ## Honesty is the feature
61	 *
62	 * Stage 4 offers only what a finished, published Kodely site genuinely does
63	 * (see the long note at the top of lib/features.ts). Each catch sits next to
64	 * its own toggle rather than in small print, and the things we cannot build are
65	 * named on the same screen with the real reason and a real alternative — never
66	 * as a greyed-out row implying that paying would unlock them. The credit figure
67	 * on stage 5 is a RANGE, because a build is an agent loop of unknown length and
68	 * a single number would be a quote nobody can honour.
69	 */
70	
71	export type InlineWizardResult = {
72	  /** The finished, editable build prompt. */
73	  prompt: string;
74	  logoDataUrl?: string;
75	  palette?: string[];
76	};
77	
78	const STAGES = [
79	  { id: "describe", label: "Describe it" },
80	  { id: "details", label: "Site details" },
81	  { id: "style", label: "Style & layout" },
82	  { id: "features", label: "Features" },
83	  { id: "review", label: "Review & build" },
84	] as const;
85	
86	const LAST = STAGES.length - 1;
87	
88	/**
89	 * The one focus ring, on a control whose real input is visually hidden.
90	 *
91	 * `k-focus` matches an element's OWN :focus-visible, which never fires on a
92	 * <label> wrapping an sr-only radio — the input is what receives focus. This is
93	 * the same `has-[:focus-visible]` treatment components/ui/Segmented.tsx uses,
94	 * with the same values as the `.k-focus` rule in app/globals.css, so the
95	 * product still has exactly one focus ring.
96	 */
97	const WRAPPED_FOCUS =
98	  "has-[:focus-visible]:outline has-[:focus-visible]:outline-2 " +
99	  "has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-[var(--brand-ring)]";
100	
101	export function InlineWizard({
102	  open,
103	  onClose,
104	  onComplete,
105	}: {
106	  open: boolean;
107	  onClose: () => void;
108	  onComplete: (result: InlineWizardResult) => void;
109	}): React.ReactNode {
110	  const [stage, setStage] = useState(0);
111	  const [answers, setAnswers] = useState<InlineAnswers>(EMPTY_INLINE_ANSWERS);
112	  /** Non-null once the review textarea has been touched. Revert throws it away. */
113	  const [edited, setEdited] = useState<string | null>(null);
114	  const [logoError, setLogoError] = useState<string | null>(null);
115	  const headingRef = useRef<HTMLHeadingElement>(null);
116	
117	  const assembled = useMemo(() => assembleInlineBrief(answers), [answers]);
118	  const promptText = edited ?? assembled;
119	
120	  // Swapping the whole panel leaves a keyboard or screen-reader user focused on
121	  // a control that no longer means what it did. The sr-only status region below
122	  // announces the change; this puts the caret where the new content starts.
123	  // Modal is a child, and child effects commit first, so the dialog is already
124	  // open and focusable by the time this runs.
125	  useEffect(() => {
126	    if (!open) return;
127	    headingRef.current?.focus();
128	  }, [open, stage]);
129	
130	  /**
131	   * Any change to an answer invalidates a hand-edit of the assembled prompt.
132	   * Silently keeping the old text would mean the palette they just changed
133	   * never reaching the build; dropping the edit is the honest failure, and the
134	   * review stage is one click away. Same contract as the public wizard.
135	   */
136	  function update(patch: Partial<InlineAnswers>) {
137	    setAnswers((prev) => ({ ...prev, ...patch }));
138	    setEdited(null);
139	  }
140	
141	  function pickCategory(category: WizardCategory) {
142	    const first = templatesForCategory(category)[0];
143	    update({ category, templateId: first?.id ?? null });
144	  }
145	
146	  function toggleFeature(id: string) {
147	    setAnswers((prev) => ({
148	      ...prev,
149	      featureIds: prev.featureIds.includes(id)
150	        ? prev.featureIds.filter((f) => f !== id)
151	        : [...prev.featureIds, id],
152	    }));
153	    setEdited(null);
154	  }
155	
156	  /**
157	   * Skip.
158	   *
159	   * On the two CHOICE stages it means "no preference", so it clears what that
160	   * stage contributed — a look half-picked and then skipped past is not what
161	   * the customer asked for. On the two TEXT stages every field is already
162	   * optional, so skipping is the same as Next and nothing typed is thrown away;
163	   * the control is still there because being able to move on without reading
164	   * the fields is the point. Same reasoning the public wizard records for its
165	   * own first step.
166	   */
167	  function skip() {
168	    if (stage === 2) {
169	      update({ lookId: null, tone: null, typeFeel: "look", density: "look", logo: null });
170	      setLogoError(null);
171	    }
172	    if (stage === 3) update({ featureIds: [] });
173	    setStage((s) => Math.min(s + 1, LAST));
174	  }
175	
176	  function finish() {
177	    const text = promptText.trim();
178	    if (!text) return;
179	    const look = answers.lookId ? getLook(answers.lookId) : undefined;
180	    onComplete({
181	      prompt: text,
182	      ...(answers.logo ? { logoDataUrl: answers.logo.dataUrl } : {}),
183	      ...(look ? { palette: look.gradient.colors } : {}),
184	    });
185	  }
186	
187	  const matches = templatesForCategory(answers.category);
188	  const chosenFeatures = selectedFeatures(answers.featureIds);
189	
190	  return (
191	    <Modal
192	      open={open}
193	      onClose={onClose}
194	      size="lg"
195	      title="Build your website"
196	      description="Five short stages. Every one is optional, and you read and edit the finished prompt before anything is built."
197	      footer={
198	        <>
199	          <div className="mr-auto flex items-center gap-1">
200	            {stage > 0 && (
201	              <Button
202	                variant="ghost"
203	                size="sm"
204	                icon={<ArrowLeft size={14} />}
205	                onClick={() => setStage((s) => Math.max(s - 1, 0))}
206	              >
207	                Back
208	              </Button>
209	            )}
210	            {/* Only on the first stage. Anywhere later "Skip this step" already
211	                walks forward, and a second control saying almost the same thing
212	                would just be two ways to guess. */}
213	            {stage === 0 && (
214	              <Button variant="ghost" size="sm" onClick={() => setStage(LAST)}>
215	                Skip to the prompt
216	              </Button>
217	            )}
218	          </div>
219	
220	          {stage < LAST ? (
221	            <>
222	              <Button variant="ghost" size="sm" onClick={skip}>
223	                Skip this step
224	              </Button>
225	              <Button
226	                variant="primary"
227	                size="sm"
228	                iconRight={<ArrowRight size={14} />}
229	                onClick={() => setStage((s) => Math.min(s + 1, LAST))}
230	              >
231	                Next
232	              </Button>
233	            </>
234	          ) : (
235	            <Button
236	              variant="primary"
237	              size="sm"
238	              icon={<Sparkles size={14} />}
239	              disabled={!promptText.trim()}
240	              onClick={finish}
241	            >
242	              Use this prompt
243	            </Button>
244	          )}
245	        </>
246	      }
247	    >
248	      {/* Stage changes are a whole-panel swap with no navigation behind them,
249	          so they are invisible to assistive tech unless announced. */}
250	      <p role="status" className="sr-only">
251	        {`Stage ${stage + 1} of ${STAGES.length}: ${STAGES[stage].label}.`}
252	      </p>
253	
254	      <div className="flex items-center justify-between gap-3 border-b border-hair pb-3">
255	        <Logo markSize={20} className="text-[0.9375rem]" />
256	        <Badge tone="brand">
257	          Stage <span className="k-num">{stage + 1}</span> of{" "}
258	          <span className="k-num">{STAGES.length}</span>
259	        </Badge>
260	      </div>
261	
262	      {/* The rail is the visual half of the indicator only — the sr-only status
263	          line above is what a screen reader hears. Hidden from the tree rather
264	          than left to compete with it: AIProgress carries its own aria-live,
265	          and two announcements for one change is one too many. */}
266	      <div aria-hidden className="mt-3.5">
267	        <AIProgress
268	          steps={stepsAt(STAGES, stage)}
269	          className="sm:flex-row sm:flex-wrap sm:gap-x-4 sm:gap-y-1.5"
270	        />
271	      </div>
272	
273	      {/* Its own scroll region so Back and Next never leave the viewport on a
274	          laptop. The dialog would otherwise scroll as a whole, putting the only
275	          way forward below the fold on the longest stages. */}
276	      <div className="mt-4 max-h-[min(56vh,30rem)] overflow-y-auto pr-1">
277	        {stage === 0 && (
278	          <DescribeStage
279	            headingRef={headingRef}
280	            answers={answers}
281	            matches={matches}
282	            onPickCategory={pickCategory}
283	            onUpdate={update}
284	          />
285	        )}
286	        {stage === 1 && <DetailsStage headingRef={headingRef} answers={answers} onUpdate={update} />}
287	        {stage === 2 && (
288	          <StyleStage
289	            headingRef={headingRef}
290	            answers={answers}
291	            onUpdate={update}
292	            logoError={logoError}
293	            onLogoError={setLogoError}
294	          />
295	        )}
296	        {stage === 3 && (
297	          <FeaturesStage
298	            headingRef={headingRef}
299	            selected={answers.featureIds}
300	            onToggle={toggleFeature}
301	          />
302	        )}
303	        {stage === 4 && (
304	          <ReviewStage
305	            headingRef={headingRef}
306	            promptText={promptText}
307	            edited={edited}
308	            onEdit={setEdited}
309	            onRevert={() => setEdited(null)}
310	            basis={{
311	              template:
312	                (answers.templateId ? getTemplate(answers.templateId) : undefined)?.name ?? null,
313	              look: (answers.lookId ? getLook(answers.lookId) : undefined)?.name ?? null,
314	              features: chosenFeatures.length,
315	              logo: answers.logo?.name ?? null,
316	            }}
317	            caveats={chosenFeatures.flatMap((f) =>
318	              f.caveat != null ? [{ id: f.id, label: f.label, caveat: f.caveat }] : [],
319	            )}
320	            answered={hasInlineAnswers(answers)}
321	          />
322	        )}
323	      </div>
324	    </Modal>
325	  );
326	}
327	
328	// ---------------------------------------------------------------------------
329	// Shared bits
330	// ---------------------------------------------------------------------------
331	
332	function StageHeading({
333	  headingRef,
334	  title,
335	  children,
336	}: {
337	  headingRef: React.RefObject<HTMLHeadingElement | null>;
338	  title: string;
339	  children?: React.ReactNode;
340	}) {
341	  return (
342	    <>
343	      <h3
344	        ref={headingRef}
345	        tabIndex={-1}
346	        className="k-h2 text-ink outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--brand-ring)]"
347	      >
348	        {title}
349	      </h3>
350	      {children != null && (
351	        <p className="mt-1.5 text-[0.8125rem] leading-relaxed text-ink-2">{children}</p>
352	      )}
353	    </>
354	  );
355	}
356	
357	/** A single-select chip. Real radios, so arrow keys and "3 of 8" come free. */
358	function Chip({
359	  name,
360	  value,
361	  checked,
362	  onSelect,
363	  children,
364	}: {
365	  name: string;
366	  value: string;
367	  checked: boolean;
368	  onSelect: () => void;
369	  children: React.ReactNode;
370	}) {
371	  return (
372	    <label
373	      className={`inline-flex cursor-pointer items-center rounded-full border px-3 py-1.5 text-xs font-medium transition-colors duration-[var(--t-1)] ${WRAPPED_FOCUS} ${
374	        checked
375	          ? "border-brand bg-brand-tint text-brand-ink dark:text-brand"
376	          : "border-hair bg-surface-2 text-ink-2 hover:border-line-mid hover:text-ink"
377	      }`}
378	    >
379	      <input
380	        type="radio"
381	        name={name}
382	        value={value}
383	        checked={checked}
384	        onChange={onSelect}
385	        className="sr-only"
386	      />
387	      {children}
388	    </label>
389	  );
390	}
391	
392	/** The line a customer needs before they tick a box, not after they publish. */
393	function Caveat({ children }: { children: React.ReactNode }) {
394	  return (
395	    <span className="mt-1.5 flex items-start gap-1.5 text-xs leading-relaxed text-warn">
396	      <Info size={13} aria-hidden className="mt-0.5 shrink-0" />
397	      <span>{children}</span>
398	    </span>
399	  );
400	}
401	
402	// ---------------------------------------------------------------------------
403	// Stage 1 — Describe
404	// ---------------------------------------------------------------------------
405	
406	function DescribeStage({
407	  headingRef,
408	  answers,
409	  matches,
410	  onPickCategory,
411	  onUpdate,
412	}: {
413	  headingRef: React.RefObject<HTMLHeadingElement | null>;
414	  answers: InlineAnswers;
415	  matches: ReturnType<typeof templatesForCategory>;
416	  onPickCategory: (category: WizardCategory) => void;
417	  onUpdate: (patch: Partial<InlineAnswers>) => void;
418	}) {
419	  return (
420	    <section>
421	      <StageHeading headingRef={headingRef} title="What are you building?">
422	        In your own words. This becomes the opening line of the brief, so a sentence about who it is
423	        for is worth more than a list of features.
424	      </StageHeading>
425	
426	      <div className="mt-4">
427	        <Textarea
428	          label="Describe it"
429	          className="min-h-24"
430	          maxLength={LIMITS.describe}
431	          // Lower-case on purpose: the first sentence becomes the tail of
432	          // "Build a one-page website for [name] — …", so the placeholder shows
433	          // the shape that reads best there.
434	          placeholder="a reformer pilates studio in Denver, for people who have tried a big-box gym and hated it"
435	          value={answers.describe}
436	          onChange={(e) => onUpdate({ describe: e.target.value })}
437	          hint="Optional, like everything here. Skip it and Kodely starts from the brief for the kind of business you pick below."
438	        />
439	      </div>
440	
441	      <fieldset className="mt-5">
442	        <legend className="text-[0.8125rem] font-medium text-ink">What kind of site is this?</legend>
443	        <p className="mt-1 text-xs leading-relaxed text-ink-2">
444	          This loads a starting brief written for that kind of business — the same ones behind the
445	          template gallery. You read and edit the whole thing on the last stage.
446	        </p>
447	        <div className="mt-3 flex flex-wrap gap-2">
448	          {WIZARD_CATEGORIES.map((option) => (
449	            <Chip
450	              key={option}
451	              name="inline-category"
452	              value={option}
453	              checked={answers.category === option}
454	              onSelect={() => onPickCategory(option)}
455	            >
456	              {option}
457	            </Chip>
458	          ))}
459	        </div>
460	      </fieldset>
461	
462	      {/* Only when the category holds more than one starter brief. With a single
463	          match it is already selected and asking would be busywork. The first is
464	          pre-selected rather than left blank, but a pre-selection nobody notices
