552	
553	/** One question. `long` answers still land inline in a sentence, so the
554	    textarea is two rows rather than an essay box. */
555	function IntakeControl({
556	  field,
557	  value,
558	  onChange,
559	}: {
560	  field: IntakeField;
561	  value: string;
562	  onChange: (value: string) => void;
563	}) {
564	  const shared = {
565	    label: field.label,
566	    hint: field.hint,
567	    placeholder: field.example,
568	    value,
569	  };
570	  return (
571	    <div className={field.wide ? "sm:col-span-2" : undefined}>
572	      {field.kind === "long" ? (
573	        <Textarea
574	          {...shared}
575	          rows={2}
576	          className="k-focus min-h-16"
577	          onChange={(e) => onChange(e.target.value)}
578	        />
579	      ) : (
580	        <Input
581	          {...shared}
582	          autoComplete="off"
583	          className="k-focus"
584	          onChange={(e) => onChange(e.target.value)}
585	        />
586	      )}
587	    </div>
588	  );
589	}
